const j = pm.response.json();
pm.test('token boş deyil', () => pm.expect(j.token).to.be.a('string').and.not.empty);
pm.test('user.email = "user1@test.com"', () => pm.expect(j.user.email).to.eql("user1@test.com"));
pm.test('Cavabda password yoxdur', () => pm.expect(JSON.stringify(j)).to.not.include('User1234'));
pm.environment.set('token', j.token);

