requests.postResponseScript:
pm.test('Status 201', () => pm.response.to.have.status(201));
const j = pm.response.json();
pm.test('id formatı ben_ + 8 simvol', () => pm.expect(j.id).to.match(/^ben_[a-z0-9]{8}$/));
pm.test('fullName = "Nigar Əliyeva"', () => pm.expect(j.fullName).to.eql("Nigar Əliyeva"));
pm.test('iban = "AZ77AIIB40060019440123456789"', () => pm.expect(j.iban).to.eql("AZ77AIIB40060019440123456789"));
pm.test('currency = "AZN"', () => pm.expect(j.currency).to.eql("AZN"));
pm.test('nickname = "Anam"', () => pm.expect(j.nickname).to.eql("Anam"));
pm.test('createdAt var', () => pm.expect(j.createdAt).to.be.a('string').and.not.empty);
pm.test('Location header = /beneficiaries/{id}', () => pm.expect(pm.response.headers.get('Location')).to.include('/beneficiaries/' + j.id));
pm.environment.set('benNigar', j.id);

